#!/usr/bin/env python3
"""whole-numbers.py <folder>: ONE CASE A FOLDER: programs pointed at whole numbers: digits that become a number . remainders of naturals by constants . Math functions of what may be undefined or null . keys with room for undefined . what must be whole . arrays typed number[] that arrive keeping int32s . words. A folder a group; every line is `label => value`."""
import os, sys
out = sys.argv[1]; cases = {}
HEAD = 'declare const console: { log(...values: unknown[]): void };\nconst show = (v: unknown): string => typeof v === "number" ? (Object.is(v, -0) ? "-0" : String(v)) : typeof v === "string" ? JSON.stringify(v) : typeof v === "bigint" ? v + "n" : v === undefined ? "undefined" : JSON.stringify(v);\nfunction row(label: string, f: () => unknown): void { let text: string; try { text = show(f()); } catch (e) { text = "THROWS " + (e as Error).name; } console.log(label + " => " + text); }\nfunction holey(a: number[], ...at: number[]): number[] { for (const i of at) delete a[i]; return a; }\n'

# 1. digits become a number in a stub
texts = ['', '0', '7', '00', '007', '12', '123456', '999999999999999', '1000000000000000', '9007199254740991', '9007199254740993', '123456789012345', '1234567890123456', '000000000000001', '0000000000000001', ' 1', '1 ', '+1', '-1', '-0', '+0', '1.', '.1', '1.5', '1e3', '1E3', '0x10', '0b11', '0o7', '1_000', '12px', 'px12', 'Infinity', '-Infinity', 'NaN', '\\t5\\n', '\\u00a05', '5\\u00a0', '\\u0661\\u0662', '\\uff11\\uff12', '1\\u00e9', '\\u00e91', '1\\u0000', '\\u00001', '1/', '1:', '/1', ':1', '09', '08', '1,5', '١']
s = HEAD + 'const texts: string[] = [' + ', '.join('"%s"' % t for t in texts) + '];\n'
s += 'const wide = (t: string): string => (t + "\\u4e00").slice(0, t.length);\nconst rope = (t: string): string => t.length < 2 ? t : t.slice(0, 1) + t.slice(1);\nconst longRope = (t: string): string => { let r = ""; for (let i = 0; i < t.length; i++) r += t[i]; return r; };\nconst part = (t: string): string => ("xx" + t + "yy").substring(2, 2 + t.length);\n'
s += 'const forms: [string, (t: string) => string][] = [["flat", t => t], ["wide", wide], ["rope", rope], ["longRope", longRope], ["part", part]];\n'
s += 'function viaNumber(t: string): number { return Number(t); }\nfunction viaPlus(t: string): number { return +t; }\nfunction viaParseInt(t: string): number { return parseInt(t); }\nfunction viaParseInt10(t: string): number { return parseInt(t, 10); }\nfunction viaParseInt0(t: string): number { return parseInt(t, 0); }\nfunction viaParseInt16(t: string): number { return parseInt(t, 16); }\nfunction viaParseInt8(t: string): number { return parseInt(t, 8); }\nfunction viaNumberParseInt(t: string): number { return Number.parseInt(t, 10); }\nfunction viaParseFloat(t: string): number { return parseFloat(t); }\nfunction viaTimes(t: string): number { return (t as any) * 1; }\nfunction viaOr(t: string): number { return (t as any) | 0; }\nfunction viaRadix(t: string, r: number): number { return parseInt(t, r); }\n'
s += 'for (const [form, make] of forms) for (const t of texts) { const v = make(t); row(form + " " + JSON.stringify(t), () => [viaNumber(v), viaPlus(v), viaParseInt(v), viaParseInt10(v), viaParseInt0(v), viaParseInt16(v), viaParseInt8(v), viaNumberParseInt(v), viaParseFloat(v), viaTimes(v), viaOr(v), viaRadix(v, 10), viaRadix(v, 0), viaRadix(v, 2), viaRadix(v, 36), viaRadix(v, 37), viaRadix(v, 10.9), viaRadix(v, -0), viaRadix(v, NaN), viaRadix(v, 4294967306)].map(show).join()); }\n'
s += 'let total = 0; for (let round = 0; round < 3; round++) for (let i = 0; i < texts.length; i++) { const n = Number(texts[i]); if (n === n) total += n % 1000; } row("sum in a loop", () => total);\n'
cases["digits"] = s

# 2. remainders of naturals by constants
consts = [1, 2, 3, 5, 7, 10, 16, 100, 255, 256, 641, 1000, 65535, 65536, 65537, 1000003, 2147483647, 2147483648, 2147483649, 4294967295, 4294967296, 4294967297, 1000000007, 9007199254740991]
vals = [0, 1, 2, 3, 6, 7, 8, 9, 10, 11, 99, 100, 101, 254, 255, 256, 257, 65535, 65536, 65537, 2147483646, 2147483647, 2147483648, 2147483649, 4294967294, 4294967295, 4294967296, 4294967297, 8589934591, 8589934592, 1e15, 9007199254740990, 9007199254740991]
s = HEAD + 'const values: number[] = [' + ', '.join(repr(int(v)) for v in vals) + '];\n'
for c in consts:
    s += 'function byLength%d(a: unknown[]): number { return a.length %% %d; }\nfunction inLoop%d(a: number[]): string { let r = ""; for (let i = 0; i < a.length; i++) { const x = a[i]; if (x >= 0 && Number.isInteger(x)) r += (x %% %d) + ","; } return r; }\nfunction counter%d(n: number): number { let t = 0; for (let i = 0; i < n; i++) t += i %% %d; return t; }\nfunction shifted%d(x: number): number { return (x >>> 0) %% %d; }\nfunction masked%d(x: number): number { return (x & 0x7fffffff) %% %d; }\nfunction absolute%d(x: number): number { return Math.abs(x | 0) %% %d; }\nfunction squared%d(i: number): number { const n = (i >>> 0) * (i >>> 0); return n %% %d; }\n' % ((c,) * 14)
    s += 'row("%d", () => [byLength%d(values), inLoop%d(values), counter%d(1000), values.map(shifted%d).join(), values.map(masked%d).join(), values.map(absolute%d).join(), [0, 1, 65535, 65536, 94906265, 94906266, 4294967295, -1, -2147483648].map(squared%d).join(), [-1, -2147483648, -2147483647, 2147483647, 0.5, -0, NaN].map(absolute%d).map(show).join()].join(" | "));\n' % ((c,) * 9)
cases["remainders"] = s

# 3. Math functions of what may be undefined or null, holes
fns1 = ['abs', 'floor', 'ceil', 'trunc', 'round', 'fround', 'sqrt', 'clz32', 'sign', 'sin', 'cos', 'tan', 'asin', 'acos', 'atan', 'sinh', 'cosh', 'tanh', 'asinh', 'acosh', 'atanh', 'exp', 'expm1', 'log', 'log1p', 'log2', 'log10', 'cbrt']
s = HEAD + 'const holes: number[] = holey([1.5, 9, -2.5, 9, 0], 1, 3); holes[9] = 4;\nconst optional: (number | undefined)[] = [1.5, undefined, -2.5, -0, NaN, Infinity, 2147483648, -2147483649, 0.49999999999999994, -0.5, 4503599627370495.5];\nconst nullable: (number | null)[] = [1.5, null, -2.5, -0, NaN];\nconst both: (number | null | undefined)[] = [null, undefined, 3];\nconst beyond: number[] = [1, 2];\n'
for f in fns1:
    s += 'function h_%s(a: number[]): string { let r = ""; for (let i = 0; i < a.length + 2; i++) r += show(Math.%s(a[i])) + ","; return r; }\nfunction o_%s(a: (number | undefined)[]): string { let r = ""; for (let i = 0; i < a.length; i++) r += show(Math.%s(a[i] as number)) + ","; return r; }\nfunction n_%s(a: (number | null)[]): string { let r = ""; for (let i = 0; i < a.length; i++) r += show(Math.%s(a[i] as number)) + ","; return r; }\nfunction b_%s(a: (number | null | undefined)[]): string { let r = ""; for (let i = 0; i < a.length; i++) r += show(Math.%s(a[i] as number)) + ","; return r; }\nfunction t_%s(a: number[]): number { let t = 0; for (let i = 0; i < a.length + 1; i++) t += Math.%s(a[i]); return t; }\n' % ((f,) * 10)
    s += 'row("%s", () => [h_%s(holes), o_%s(optional), n_%s(nullable), b_%s(both), show(t_%s(beyond)), show(t_%s(holes))].join(" | "));\n' % ((f,) * 7)
for f in ['imul', 'atan2', 'hypot', 'max', 'min', 'pow']:
    s += 'function two_%s(a: (number | undefined)[], b: (number | null)[]): string { let r = ""; for (let i = 0; i < a.length; i++) for (let j = 0; j < b.length; j++) r += show(Math.%s(a[i] as number, b[j] as number)) + ","; return r; }\nrow("%s", () => two_%s(optional, nullable) + " | " + two_%s([undefined, 2], [null, 3]));\n' % ((f,) * 5)
s += 'function bump(a: number[]): string { for (let i = 0; i < a.length; i++) a[i]++; return a.map(show).join(); }\nrow("a[i]++ over holes", () => bump(holey([1, 9, 3], 1)));\nfunction negate(a: number[]): string { let r = ""; for (let i = 0; i < a.length + 1; i++) r += show(-a[i]) + show(+a[i]) + show(~a[i]) + show(a[i] | 0) + show(a[i] >>> 0) + ","; return r; }\nrow("unary over holes", () => negate(holey([1.5, 9, -0], 1)));\n'
cases["math"] = s

# 4. keys with room for undefined
s = HEAD + 'const keys: number[] = [0, -0, 1, 1.5, NaN, 2147483647, 2147483648, -2147483648, -2147483649, 4294967296, 1e21, Infinity, -Infinity, 5e-324, 9, 7]; delete keys[14];\n'
s += 'function fill(): Map<number | undefined, string> { const m = new Map<number | undefined, string>(); for (let i = 0; i < keys.length; i++) m.set(keys[i], "at " + i); return m; }\nfunction gets(m: Map<number | undefined, string>, a: number[]): string { let r = ""; for (let i = 0; i < a.length + 1; i++) r += m.get(a[i]) + "|" + m.has(a[i]) + ","; return r; }\nfunction fillSet(a: number[]): Set<number | undefined> { const s = new Set<number | undefined>(); for (let i = 0; i < a.length; i++) s.add(a[i]); return s; }\nfunction removes(m: Map<number | undefined, string>, a: number[]): string { let r = ""; for (let i = 0; i < a.length; i++) r += m.delete(a[i]) + ","; return r + m.size; }\n'
s += 'row("size", () => fill().size); row("keys", () => [...fill().keys()].map(show).join()); row("gets", () => gets(fill(), keys)); row("gets of computed", () => gets(fill(), [0 * -1, 3 - 2, 0.5 + 1, 0 / 0, 2 ** 31 - 1, 2 ** 31, 7.0, 14 / 2, -(2 ** 31), 1e21 + 1]));\nrow("set", () => [...fillSet(keys)].map(show).join()); row("removes", () => removes(fill(), keys)); row("undefined key", () => { const m = fill(); return [m.get(undefined), m.has(undefined), m.get([][0])].join(); });\nfunction typed(m: Map<number, number>, a: number[]): number { let t = 0; for (let i = 0; i < a.length; i++) t += m.get(a[i]) ?? -1; return t; }\nrow("a map of numbers", () => typed(new Map([[0, 1], [1, 2], [NaN, 4], [1.5, 8]]), holey([-0, 1, NaN, 1.5, 2, 9, 0], 5)));\nfunction counts(a: number[]): string { const m = new Map<number, number>(); for (let i = 0; i < a.length; i++) m.set(a[i], (m.get(a[i]) ?? 0) + 1); return [...m].map(([k, v]) => show(k) + ":" + v).join(); }\nrow("counts", () => counts(holey([1, 1.0, -0, 0, NaN, NaN, 9, 9, 2 ** 31, 2147483648], 6, 7)));\n'
cases["keys"] = s

# 5. what must be whole
s = HEAD + 'const places: number[] = [0, 1, 2, -1, -0, 0.5, 1.9999, NaN, Infinity, -Infinity, 2147483647, 2147483648, 4294967295, 4294967296, 1e21, 9, 3]; delete places[15];\nconst text: string = "abcd\\u00e9\\u4e00";\nconst list: number[] = [10, 20, 30, 40];\nconst words: string[] = ["w0", "w1", "w2"];\n'
for name, expr in [('charCodeAt', 'text.charCodeAt(a[i])'), ('codePointAt', 'text.codePointAt(a[i])'), ('charAt', 'text.charAt(a[i])'), ('at', 'text.at(a[i])'), ('index', 'text[a[i]]'), ('element', 'list[a[i]]'), ('word', 'words[a[i]]'), ('listAt', 'list.at(a[i])'), ('slice', 'text.slice(a[i])'), ('substring', 'text.substring(a[i])'), ('repeat', '"x".repeat(a[i]).length'), ('toFixed', '(1.25).toFixed(a[i])'), ('toString', '(255).toString(a[i])'), ('newArray', 'new Array(a[i]).length'), ('fromCharCode', 'String.fromCharCode(a[i])'), ('padStart', '"x".padStart(a[i] > 20 ? 20 : a[i], "-")'), ('indexOfFrom', 'text.indexOf("c", a[i])'), ('shift', '1 << a[i]'), ('typedArray', 'bytes[a[i]]'), ('includesFrom', 'list.includes(30, a[i])')]:
    s += 'function f_%s(a: number[]): string { let r = ""; for (let i = 0; i < a.length + 1; i++) { let v: string; try { v = show(%s); } catch (e) { v = (e as Error).name; } r += v + ","; } return r; }\n' % (name, expr)
    s += 'row("%s", () => f_%s(places));\n' % (name, name)
s = s.replace('const words: string[]', 'const bytes: Uint8Array = new Uint8Array([5, 6, 7]);\nconst words: string[]')
s += 'function stores(a: number[]): string { const t: number[] = [0, 0, 0]; for (let i = 0; i < a.length; i++) { const p = a[i]; if (p === undefined || p < 6 || p !== p) t[p] = i; } return JSON.stringify(t) + Object.keys(t).join(); }\nrow("stores", () => stores(places));\n'
cases["places"] = s

# 6. arrays typed number[] that arrive keeping int32s, and every odd array
makers = [('parsed', 'JSON.parse("[1,2,3,4]")'), ('literal', '[1, 2, 3, 4]'), ('untyped', 'untypedInts()'), ('doubles', '[1.5, 2.5, 3.5, 4.5]'), ('mixed', '[1, 2.5, 3, 4]'), ('holes', 'holey([1, 9, 3, 4], 1)'), ('parsedEmpty', 'JSON.parse("[]")'), ('frozen', 'Object.freeze([1, 2, 3, 4]) as number[]'), ('sealed', 'Object.seal([1, 2, 3, 4])'), ('named', 'Object.assign([1, 2, 3, 4], { extra: 1 })'), ('subclass', 'Sub.from([1, 2, 3, 4])'), ('cloned', 'structuredClone([1, 2, 3, 4])'), ('big', 'Array.from({ length: 100 }, (_, i) => i)'), ('sparse', '(() => { const a: number[] = [1, 2]; a[5000] = 3; return a; })()'), ('withUndefined', '(JSON.parse("[1,2]") as number[]).concat([undefined as unknown as number])'), ('ofNew', 'new Array<number>(4).fill(7)'), ('sliced', '[0, 1, 2, 3, 4].slice(1)'), ('negativeZero', '[1, -0, 3]'), ('maxInt', '[2147483647, -2147483648, 0]'), ('strings', '(["a", "b"] as unknown as number[])')]
uses = [('sum', 'let t = 0; for (let i = 0; i < a.length; i++) t += a[i]; return t;'), ('max', 'let t = -Infinity; for (let i = 0; i < a.length; i++) if (a[i] > t) t = a[i]; return t;'), ('count', 'let t = 0; for (let i = 0; i < a.length; i++) if (a[i] === 3) t++; return t;'), ('ofLoop', 'let t = 0; for (const x of a) t += x; return t;'),
        ('fill', 'for (let i = 0; i < a.length; i++) a[i] = 0.5; return a;'), ('fillInts', 'for (let i = 0; i < a.length; i++) a[i] = i; return a;'), ('scale', 'for (let i = 0; i < a.length; i++) a[i] *= 1.5; return a;'), ('grow', 'for (let i = 0; i < 3; i++) a[a.length] = i + 0.5; return a;'), ('push', 'for (let i = 0; i < 3; i++) a.push(i); return a;'),
        ('texts', 'let r = ""; for (let i = 0; i < a.length; i++) r += String(a[i]) + ";"; return r;'), ('template', 'let r = ""; for (let i = 0; i < a.length; i++) r += `${a[i]};`; return r;'), ('kept', 'const k: unknown[] = []; for (let i = 0; i < a.length; i++) k.push(a[i]); return k;'), ('handed', 'let r = ""; for (let i = 0; i < a.length; i++) r += takes(a[i]); return r;'),
        ('notEntered', 'let t = 0; for (let i = 0; i < 0; i++) t += a[i]; return t;'), ('shrinks', 'let t = 0; for (let i = 0; i < a.length; i++) { t += a[i]; if (i === 1) a.length = 2; } return t;'), ('beyond', 'let t = 0; for (let i = 0; i < a.length + 2; i++) t += a[i] ?? 100; return t;'), ('backwards', 'let t = 0; for (let i = a.length - 1; i >= 0; i--) t = t * 2 + a[i]; return t;'),
        ('storesNaN', 'for (let i = 0; i < a.length; i++) a[i] = i === 1 ? NaN : a[i]; return a;'), ('storesMinusZero', 'for (let i = 0; i < a.length; i++) a[i] = -0; return a.map(x => Object.is(x, -0)).join();'), ('swaps', 'for (let i = 0, j = a.length - 1; i < j; i++, j--) { const x = a[i]; a[i] = a[j]; a[j] = x; } return a;'), ('compare', 'let r = ""; for (let i = 0; i + 1 < a.length; i++) r += a[i] < a[i + 1] ? "<" : a[i] === a[i + 1] ? "=" : ">"; return r;')]
s = HEAD + 'import { untypedInts } from "./untyped.js";\nclass Sub extends Array<number> {}\nfunction takes(v: unknown): string { return typeof v + ":" + String(v) + ";"; }\n'
for u, body in uses: s += 'function u_%s(a: number[]): unknown { %s }\n' % (u, body)
s += 'function two(a: number[], b: number[]): unknown { for (let i = 0; i < a.length; i++) b[i] = a[i] + 0.5; return [a, b]; }\nfunction maybe(a: number[] | undefined, n: number): number { let t = 0; for (let i = 0; i < n; i++) t += a![i]; return t; }\n'
for m, expr in makers:
    for u, _ in uses:
        s += 'row("%s %s", () => { const a: number[] = %s; const r = u_%s(a); return [r, a, a.length, Object.keys(a).length]; });\n' % (m, u, expr, u)
    s += 'row("%s aliased", () => { const a: number[] = %s; return two(a, a); });\nrow("%s twice", () => { const a: number[] = %s; return [u_sum(a), u_scale(a), u_sum(a), u_fillInts(a), u_sum(a)]; });\n' % (m, expr, m, expr)
s += 'row("undefined, not entered", () => maybe(undefined, 0)); row("undefined, entered", () => maybe(undefined, 1));\nconst shared: number[] = [1, 2, 3]; function literalAgain(): number[] { return [1, 2, 3]; }\nrow("a literal made twice", () => { const first = literalAgain(); u_scale(first); return [first, literalAgain()]; });\n'
cases["arrays"] = s

# 7. words
vals32 = [0, 1, -1, 2, -2, 255, 256, 65535, 65536, 2147483647, -2147483648, -2147483647, 1073741824, -1073741824, 0x55555555, -0x55555556]
s = HEAD + 'const words: number[] = [' + ', '.join(map(str, vals32)) + '];\n'
exprs = ['((x << 3) ^ (x >> 2)) & 255', '(x & y) | (x ^ y)', '(x | y) & ~y', '((x | 0) ^ (y | 0)) >>> 0', '(x & 0x80000000) !== 0', '(x & y) === y', '(x | y) === -1', '(x ^ y) === 0', '((x & 0xff) << 24) | (y & 0xffffff)', '(x >> 31) ^ y', '(x >>> 31) + (y >>> 31)', '((x | 0) + 0.5) * 2', '(x | 0) / 2', '((x & y) | 0) * 1.5', '(x << y) >> y', '(x >>> y) | 0', '~(x & y) + 1', '(x & -x) === x', '((x ^ (x >> 31)) - (x >> 31))', '(x | 0) === (y | 0)', '(x >>> 0) === (y >>> 0)', '(x & 0xffff) * (y & 0xffff)', 'Math.imul(x, y) ^ (x + y | 0)', '((x | 0) < (y | 0)) === ((x >>> 0) < (y >>> 0))', '(x & 1 ? y : ~y) & 0xf0f0f0f0', '(x + y | 0) + (x - y | 0) | 0', '(x * 2 | 0) >> 1']
for i, e in enumerate(exprs):
    s += 'function e%d(x: number, y: number): unknown { return %s; }\nfunction l%d(a: number[]): string { let r = ""; for (let i = 0; i < a.length; i++) for (let j = 0; j < a.length; j++) { const x = a[i] | 0, y = a[j] | 0; r += show(%s) + ","; } return r; }\n' % (i, e, i, e)
    s += 'row(%s, () => { let r = ""; for (const x of words) for (const y of words) r += show(e%d(x, y)) + ","; return r === l%d(words) ? r : "THE TWO FORMS DIFFER " + r + " | " + l%d(words); });\n' % (repr(e).replace("'", '"'), i, i, i)
s += 'class Flags { bits: number = 0; small: number = 0; constructor(b: number, s: number) { this.bits = b | 0; this.small = s & 255; } has(m: number): boolean { return (this.bits & m) !== 0; } all(m: number): boolean { return (this.bits & m) === m; } half(): number { return this.bits / 2; } plus(): number { return this.bits + 0.25; } }\nrow("fields", () => words.map(w => { const f = new Flags(w, w); return [f.has(1), f.has(-2147483648), f.all(255), f.half(), f.plus(), f.small].map(show).join("/"); }).join());\n'
cases["words"] = s

for name, text in cases.items():
    os.makedirs(f"{out}/{name}", exist_ok=True); open(f"{out}/{name}/main.ts", "w").write(text)
open(f"{out}/arrays/untyped.js", "w").write('export function untypedInts() { const a = []; for (let i = 1; i <= 4; i++) a.push(i); return a; }\n')
print(len(cases), "programs:", " ".join("%s %d lines" % (k, v.count("\n")) for k, v in cases.items()))
